import {REVOLT_ART_IDS} from './revolt-data.js?v=0.90.48';
import {COSSENNE_PEOPLE} from './cossenne-data.js?v=0.90.48';
import {MOUNTAIN_NPC_IDS} from './mountain-art.js?v=0.87.0';
import {SIDE_TRAINER_ART,SIDE_TRAINER_IDS,RESTORED_TRAINER_ART} from './side-trainer-art.js?v=0.90.16';
// Four facing rows, with a passing pose between opposite planted-foot poses.
export const WORLD_CHARACTER_HEIGHT=52;
export const WORLD_WALK_IDS=['NPC-BERRY-MABEL','LDR-05',...REVOLT_ART_IDS,...COSSENNE_PEOPLE,...SIDE_TRAINER_IDS,...MOUNTAIN_NPC_IDS,'CHR-AIMON','CHR-KURG','CHR-AERIC','TRN-C01-001','TRN-C01-002','TRN-C01-003','TRN-C02-001','TRN-C02-002','LDR-01','LDR-02','SHOP-CIV','SHOP-DOR','SHOP-PHI','CHR-TREASURE','CHR-SALVAGER','CHR-BLOOM-ELITE'];
export function worldWalkFrame(entity){const rows={down:0,left:1,up:2,right:3};const progress=entity.step?.duration>0?Math.max(0,Math.min(.999999,entity.step.elapsed/entity.step.duration)):0;const stride=Number.isFinite(entity.stride)?Math.abs(Math.trunc(entity.stride))%2:0;return {row:rows[entity.facing]??0,frame:entity.step?Math.floor((stride+progress)*2)%4:0};}
const people={'cybressa-provost':'LDR-03','cybressa-clerk':'SHOP-PHI','cybressa-ferryman':'SHOP-DOR','weir-ferryman':'SHOP-DOR','cybressa-merchant':'SHOP-PHI','salt-merchant':'SHOP-PHI','cybressa-boatwright':'CHR-TREASURE','backwaters-boatwright':'CHR-TREASURE','cybressa-trials':'TRN-C01-001','cybressa-trial-challenge':'TRN-C01-001',kurg:'CHR-KURG',aeric:'CHR-AERIC','local-aeric':'CHR-AERIC',beric:'TRN-C01-001',aldren:'LDR-01',yselle:'LDR-02','pate-mother':'TRN-C01-003','pate-father':'SHOP-CIV','trade-mother':'TRN-C01-003','trade-grandfather':'SHOP-CIV',bystander:'SHOP-CIV','tunnel-guide':'SHOP-CIV','scrub-refugees':'SHOP-DOR','wounded-column':'SHOP-DOR','hospice-volunteer':'SHOP-PHI','hospice-nurse':'SHOP-PHI','rescued-soldier':'TRN-C01-002','rescue-leader':'TRN-RESCUE-4','rescue-scout':'TRN-RESCUE-1','rescue-kora':'TRN-RESCUE-2','rescue-sile':'TRN-RESCUE-3','fishing-warden':'SHOP-CIV','fishing-rival-mara':'TRN-C01-003','fishing-rival-ivo':'SHOP-CIV','hospice-ward-nurse':'SHOP-PHI','hospice-soldier':'TRN-C02-002',patients:'SHOP-DOR','lost-pilgrim':'SHOP-DOR',stablehand:'SHOP-DOR','surrendered-soldier':'TRN-C02-002'};
export function worldPortrait(entity,bloom=false){if(RESTORED_TRAINER_ART.includes(entity.id))return entity.id;if(entity.revoltCharacter)return entity.revoltCharacter;if(COSSENNE_PEOPLE.includes(entity.id))return entity.id;if(['cs-warden','cs-warden-local'].includes(entity.id))return 'LDR-04';if(MOUNTAIN_NPC_IDS.includes(entity.id))return entity.id;if(SIDE_TRAINER_ART[entity.id])return entity.id;if(entity.isPlayer)return 'CHR-AIMON';if(entity.shopkeeper)return entity.shopkeeper;if(people[entity.id])return people[entity.id];if(/^waranCave[1-5]-npc$/.test(entity.id||''))return ['CHR-TREASURE','CHR-SALVAGER','CHR-TREASURE','CHR-SALVAGER','CHR-SALVAGER'][Number(entity.id.match(/\d/)[0])-1];if(entity.id?.startsWith('TRN-RT-'))return (bloom?['SHOP-DOR','SHOP-PHI']:['TRN-C01-002','TRN-C01-003','TRN-C02-001','TRN-C02-002'])[(Number(entity.id.slice(-3))-1)%(bloom?2:4)];if(entity.id?.startsWith('TRN-'))return entity.id;const choices=bloom?['SHOP-PHI','SHOP-DOR','SHOP-PHI','SHOP-DOR']:['TRN-C01-003','SHOP-CIV','SHOP-CIV','CHR-AERIC'];return choices[entity.civilian??(Number(entity.sprite)||0)]||choices[0];}
export function portraitBounds(image){const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const c=canvas.getContext('2d',{willReadFrequently:true});c.drawImage(image,0,0);const pixels=c.getImageData(0,0,canvas.width,canvas.height).data;let left=canvas.width,top=canvas.height,right=0,bottom=0;for(let y=0;y<canvas.height;y++)for(let x=0;x<canvas.width;x++)if(pixels[(y*canvas.width+x)*4+3]>20){left=Math.min(left,x);top=Math.min(top,y);right=Math.max(right,x);bottom=Math.max(bottom,y);}return left<=right?[left,top,right-left+1,bottom-top+1]:[0,0,canvas.width,canvas.height];}
export function drawWorldCharacter(c,entity,image,bounds){c.save();c.fillStyle='#0006';c.beginPath();c.ellipse(entity.px,entity.py-1,10,3,0,0,Math.PI*2);c.fill();c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';if(image.worldWalk){const {row,frame}=worldWalkFrame(entity),cell=image.naturalWidth/4,size=WORLD_CHARACTER_HEIGHT*128/112;c.drawImage(image,frame*cell,row*cell,cell,cell,entity.px-size/2,entity.py+4-size*120/128,size,size);}else{const [x,y,w,h]=bounds||[0,0,image.naturalWidth,image.naturalHeight],height=WORLD_CHARACTER_HEIGHT,width=Math.min(44,height*w/h);c.drawImage(image,x,y,w,h,entity.px-width/2,entity.py-height+4,width,height);}c.restore();}
